<template>
  <section class="smc-academy">
    <header class="hero">
      <div class="hero-copy">
        <div class="eyebrow"><span class="live-dot"></span> ACADEMIA INTERACTIVA · SMART MONEY CONCEPTS</div>
        <h1>Leé el mercado.<br /><em>Entendé la estructura.</em></h1>
        <p class="hero-lead">Un recorrido visual y práctico basado en «Domina el Mercado con Smart Money Concepts»: desde la estructura y los swing points hasta los modelos de trading ICT, con gráficos paso a paso.</p>
        <div class="hero-actions">
          <button class="btn btn-primary" @click="selectLesson(1)">Empezar a aprender <span>↗</span></button>
          <button class="btn btn-quiet" @click="activeTab = 'laboratorio'">Abrir laboratorio visual</button>
        </div>
        <div class="hero-meta"><span>52 capítulos SMC + 4 de nivelación</span><i></i><span>7 partes temáticas</span><i></i><span>Práctica interactiva</span></div>
      </div>
      <div class="hero-art"><CandleChart :scene="scenes.bos" compact /></div>
    </header>

    <div class="progress-strip">
      <div class="progress-label"><span>Tu recorrido de aprendizaje</span><strong>{{ completedCount }} / {{ chapters.length }} capítulos</strong></div>
      <div class="progress-track"><span :style="{ width: `${progressPercent}%` }"></span></div>
      <span class="progress-percent">{{ progressPercent }}%</span>
    </div>

    <nav class="main-tabs" aria-label="Secciones de la academia">
      <button :class="{ active: activeTab === 'curso' }" @click="activeTab = 'curso'">Ruta de aprendizaje</button>
      <button :class="{ active: activeTab === 'laboratorio' }" @click="activeTab = 'laboratorio'">Laboratorio visual</button>
      <button :class="{ active: activeTab === 'glosario' }" @click="activeTab = 'glosario'">Glosario SMC</button>
      <button :class="{ active: activeTab === 'metodo' }" @click="activeTab = 'metodo'">Checklist de análisis</button>
    </nav>

    <main v-if="activeTab === 'curso'" class="course-layout">
      <aside class="course-sidebar">
        <div class="sidebar-heading"><span>CONTENIDO DEL LIBRO</span><strong>{{ filteredChapters.length }} lecciones</strong></div>
        <label class="search-box"><span>⌕</span><input v-model="search" placeholder="Buscar concepto o capítulo…" /></label>
        <div class="part-filter"><button :class="{ selected: selectedPart === -1 }" @click="selectedPart = -1">Todo</button><button v-for="part in parts" :key="part.id" :class="{ selected: selectedPart === part.id }" @click="selectedPart = part.id">{{ part.short }}</button></div>
        <div v-for="part in visibleParts" :key="part.id" class="chapter-group">
          <div class="group-title"><span>{{ part.name }}</span><small>{{ partChapters(part.id).filter(c => completed.includes(c.id)).length }}/{{ partChapters(part.id).length }}</small></div>
          <button v-for="chapter in partChapters(part.id)" :key="chapter.id" class="chapter-link" :class="{ chosen: selectedChapter === chapter.id, done: completed.includes(chapter.id) }" @click="selectLesson(chapter.id)">
            <span class="chapter-num">{{ String(chapter.id).padStart(2,'0') }}</span><span class="chapter-name">{{ chapter.title }}</span><span v-if="completed.includes(chapter.id)" class="done-mark">✓</span>
          </button>
        </div>
        <p v-if="filteredChapters.length === 0" class="empty-state">No encontré capítulos con esa búsqueda.</p>
      </aside>

      <article class="lesson-panel" v-if="currentChapter">
        <div class="lesson-kicker"><span>PARTE {{ currentPart?.number }}</span><span>LIBRO · PÁG. {{ bookPages[currentChapter.id - 1] }}</span><span>CAPÍTULO {{ currentChapter.id <= 4 ? `0.${currentChapter.id}` : currentChapter.id - 4 }}</span><span class="lesson-status" :class="{ finished: completed.includes(currentChapter.id) }">{{ completed.includes(currentChapter.id) ? 'COMPLETADO' : 'EN ESTUDIO' }}</span></div>
        <div class="lesson-title-row"><div><h2>{{ currentChapter.title }}</h2><p class="lesson-subtitle">{{ currentChapter.subtitle || currentPart?.name }}</p></div><button class="bookmark-btn" :class="{ saved: completed.includes(currentChapter.id) }" @click="toggleCompleted(currentChapter.id)" :aria-label="completed.includes(currentChapter.id) ? 'Marcar pendiente' : 'Marcar capítulo completado'">{{ completed.includes(currentChapter.id) ? '✓' : '○' }}</button></div>
        <div class="lesson-visual">
          <div class="visual-heading"><div><span class="visual-overline">LÁMINA DIDÁCTICA · PASO A PASO</span><h3>{{ lessonScene.title }}</h3><p class="scene-caption">{{ lessonScene.caption }}</p></div><span class="visual-badge">ESQUEMA SMC</span></div>
          <CandleChart :scene="lessonScene.scene" />
          <div class="visual-controls"><span class="scene-explainer">{{ lessonScene.rule }}</span></div>
        </div>

        <section class="lesson-explanation">
          <div class="section-label">01 — EXPLICACIÓN CLARA</div>
          <h3>{{ lessonContent(currentChapter.id).heading }}</h3>
          <p>{{ lessonContent(currentChapter.id).intro }}</p>
          <div class="everyday-example">
            <div class="everyday-label"><span>02</span><div><strong>BAJALO A LA VIDA REAL</strong><small>Una analogía para entender la lógica</small></div></div>
            <h4>{{ dailyExample(currentChapter.id).title }}</h4>
            <p>{{ dailyExample(currentChapter.id).story }}</p>
            <div class="market-translation"><strong>¿Y en el gráfico?</strong><p>{{ dailyExample(currentChapter.id).market }}</p></div>
            <div class="example-caution"><strong>Qué no hay que confundir:</strong> {{ dailyExample(currentChapter.id).caution }}</div>
          </div>
          <div class="key-points"><div v-for="(point,i) in lessonContent(currentChapter.id).points" :key="point.title" class="key-point"><span class="point-number">0{{ i+1 }}</span><div><strong>{{ point.title }}</strong><p>{{ point.text }}</p></div></div></div>
          <div class="trader-note"><span class="note-icon">i</span><div><strong>En lenguaje trader</strong><p>{{ lessonContent(currentChapter.id).traderNote }}</p></div></div>
          <div class="mistake-box"><div class="mistake-heading"><span>ERROR HABITUAL</span><span>↗</span></div><p>{{ lessonContent(currentChapter.id).mistake }}</p></div>
        </section>

        <section class="lesson-practice">
          <div class="section-label">03 — COMPROBÁ SI LO ENTENDISTE</div>
          <h3>{{ lessonContent(currentChapter.id).question }}</h3>
          <div class="quiz-options"><button v-for="(option,i) in lessonContent(currentChapter.id).options" :key="option" :class="{ picked: quizAnswer === i, correct: quizSubmitted && i === lessonContent(currentChapter.id).correct, incorrect: quizSubmitted && quizAnswer === i && i !== lessonContent(currentChapter.id).correct }" @click="chooseAnswer(i)" :disabled="quizSubmitted"><span>{{ String.fromCharCode(65+i) }}</span>{{ option }}</button></div>
          <div v-if="quizSubmitted" class="quiz-feedback" :class="{ good: quizAnswer === lessonContent(currentChapter.id).correct }"><strong>{{ quizAnswer === lessonContent(currentChapter.id).correct ? '¡Bien leído!' : 'Revisemos la lógica' }}</strong><p>{{ lessonContent(currentChapter.id).feedback }}</p><button class="text-button" @click="resetQuiz">Intentar de nuevo</button></div>
          <div class="lesson-footer"><span>{{ completed.includes(currentChapter.id) ? 'Capítulo completado' : 'Marcá el capítulo como completado al terminar' }}</span><div class="footer-actions"><button class="btn btn-quiet" @click="previousLesson" :disabled="selectedChapter <= 1">← Anterior</button><button class="btn btn-primary" @click="nextLesson">Siguiente capítulo →</button></div></div>
        </section>
      </article>
    </main>

    <main v-else-if="activeTab === 'laboratorio'" class="lab-layout">
      <div class="lab-intro"><div class="section-label">PRACTICÁ SIN ARRIESGAR CAPITAL</div><h2>Laboratorio de estructura</h2><p>Elegí un concepto y mirá cómo cambia la lectura del mismo movimiento. El gráfico es esquemático: sirve para aprender la lógica, no representa un activo real.</p></div>
      <div class="lab-grid"><div class="lab-chart-card"><div class="visual-heading"><div><span class="visual-overline">PRECIO SIMULADO</span><h3>{{ visualModes.find(m => m.id === visualMode)?.label }}</h3></div></div><CandleChart :scene="labScene" compact /><div class="visual-controls"><button v-for="mode in visualModes" :key="mode.id" :class="{ active: visualMode === mode.id }" @click="visualMode = mode.id">{{ mode.label }}</button></div></div>
        <aside class="lab-explainer"><span class="visual-overline">QUÉ TENÉS QUE MIRAR</span><h3>{{ labExplanation.title }}</h3><p>{{ labExplanation.body }}</p><ul><li v-for="item in labExplanation.checks" :key="item">{{ item }}</li></ul><div class="lab-rule"><strong>Regla de oro</strong><p>No clasifiques una figura aislada. Primero contexto, después nivel estructural, luego ruptura y reacción.</p></div></aside></div>
      <div class="lab-bottom-grid"><div class="mini-concept"><span>01 / ESTRUCTURA</span><h3>¿Quién domina?</h3><p>HH + HL sugiere estructura alcista; LH + LL, bajista. Si el precio oscila dentro de un rango, puede estar consolidando.</p></div><div class="mini-concept"><span>02 / CONFIRMACIÓN</span><h3>¿Qué nivel rompió?</h3><p>Una ruptura a favor de la tendencia puede ser BOS. Una ruptura contra la estructura previa puede ser CHOCH; el libro también diferencia MSS por el desplazamiento.</p></div><div class="mini-concept"><span>03 / CONTEXTO</span><h3>¿Dónde está?</h3><p>Relacioná la estructura con liquidez, FVG, Order Blocks, premium/discount y temporalidades superiores. La confluencia importa.</p></div></div>
    </main>

    <main v-else-if="activeTab === 'glosario'" class="glossary-layout"><div class="lab-intro"><div class="section-label">CONSULTA RÁPIDA</div><h2>Glosario SMC</h2><p>Buscá las siglas del libro y repasá el significado en castellano.</p><label class="search-box glossary-search"><span>⌕</span><input v-model="glossarySearch" placeholder="Buscar BOS, CHOCH, FVG, liquidez…" /></label></div><div class="glossary-grid"><article v-for="item in filteredGlossary" :key="item.term" class="glossary-card"><div class="glossary-term">{{ item.term }}<span>{{ item.family }}</span></div><h3>{{ item.name }}</h3><p>{{ item.definition }}</p><small v-if="item.caution">Ojo: {{ item.caution }}</small></article></div><p v-if="!filteredGlossary.length" class="empty-state">No encontré ese término.</p></main>

    <main v-else class="method-layout"><div class="lab-intro"><div class="section-label">ANTES DE TOMAR UNA DECISIÓN</div><h2>Checklist de análisis SMC</h2><p>Usá esta lista para revisar el contexto sin saltar directamente a una entrada. Los checks se reinician cuando recargás el componente.</p></div><div class="method-grid"><section class="method-card"><div class="method-number">01</div><h3>Contexto y estructura</h3><label v-for="item in checklist.structure" :key="item" class="check-row"><input type="checkbox" v-model="checkedItems" :value="item"/><span>{{ item }}</span></label></section><section class="method-card"><div class="method-number">02</div><h3>Liquidez y zonas</h3><label v-for="item in checklist.zones" :key="item" class="check-row"><input type="checkbox" v-model="checkedItems" :value="item"/><span>{{ item }}</span></label></section><section class="method-card"><div class="method-number">03</div><h3>Confirmación</h3><label v-for="item in checklist.confirmation" :key="item" class="check-row"><input type="checkbox" v-model="checkedItems" :value="item"/><span>{{ item }}</span></label></section><section class="method-card"><div class="method-number">04</div><h3>Riesgo y disciplina</h3><label v-for="item in checklist.risk" :key="item" class="check-row"><input type="checkbox" v-model="checkedItems" :value="item"/><span>{{ item }}</span></label></section></div><div class="checklist-summary"><div><strong>{{ checkedItems.length }} de {{ allChecklistItems.length }} controles revisados</strong><p>SMC no elimina la incertidumbre. La gestión del riesgo sigue siendo imprescindible.</p></div><button class="btn btn-quiet" @click="checkedItems = []">Limpiar checklist</button></div><div class="disclaimer"><strong>Nota educativa</strong><p>Este componente es material de estudio, no una señal de compra o venta. Las etiquetas SMC pueden variar entre traders; contrastá las definiciones con el capítulo correspondiente del PDF y validalas con backtesting.</p></div></main>
    <footer class="academy-footer"><span>SMC ACADEMY</span><span>Estudiá el contexto. Confirmá la estructura. Gestioná el riesgo.</span><button @click="scrollTop">Volver arriba ↑</button></footer>
  </section>
</template>

<script setup>
import { computed, ref, watch } from 'vue'
import CandleChart from './CandleChart.vue'
import { parts, chapters as lessonCatalog, sceneTypeForChapter, sceneDetails, lessonContent, dailyExample, glossary, checklist } from '../data/content.js'
import { scenes, sceneFor, sceneOverride, sceneTypeFix } from '../data/scenes.js'

const activeTab = ref('curso'), selectedChapter = ref(1), selectedPart = ref(-1), search = ref(''), glossarySearch = ref('')
const visualMode = ref('estructura'), quizAnswer = ref(null), quizSubmitted = ref(false), checkedItems = ref([]), completed = ref([])
// Páginas de inicio de cada capítulo según el índice de Libro_SMC.pdf (0.1–0.4 y 1–52).
const bookPages = [16,19,22,25,28,35,40,43,45,50,57,60,65,70,78,83,88,94,97,101,105,110,116,120,124,127,130,136,142,148,152,156,160,166,170,174,177,181,183,190,196,208,211,215,221,224,227,229,234,245,250,256,261,264,271,274]

const chapters = lessonCatalog
const currentChapter = computed(() => lessonCatalog.find(c => c.id === selectedChapter.value) || lessonCatalog[0])
const currentPart = computed(() => parts.find(p => p.id === currentChapter.value?.part))
const completedCount = computed(() => completed.value.length)
const progressPercent = computed(() => Math.round(completedCount.value / lessonCatalog.length * 100))
const filteredChapters = computed(() => lessonCatalog.filter(c => (selectedPart.value === -1 || c.part === selectedPart.value) && `${c.title} ${c.subtitle} ${c.id}`.toLowerCase().includes(search.value.toLowerCase())))
const visibleParts = computed(() => parts.filter(p => selectedPart.value === -1 || p.id === selectedPart.value).filter(p => partChapters(p.id).some(c => filteredChapters.value.includes(c))))
const partChapters = id => filteredChapters.value.filter(c => c.part === id)
const filteredGlossary = computed(() => glossary.filter(g => `${g.term} ${g.name} ${g.definition} ${g.family}`.toLowerCase().includes(glossarySearch.value.toLowerCase())))

const visualModes = [{ id: 'estructura', label: 'Estructura' }, { id: 'choch', label: 'CHOCH' }, { id: 'fvg', label: 'FVG / IFVG' }, { id: 'ob', label: 'Order Block' }, { id: 'breaker', label: 'Breaker Block' }, { id: 'liquidez', label: 'Liquidez' }]
const labScene = computed(() => ({ estructura: scenes.trend, choch: scenes.choch, fvg: scenes.fvg, ob: scenes.ob, breaker: scenes.breaker, liquidez: scenes.liquidity }[visualMode.value]))
const lessonScene = computed(() => {
  const id = currentChapter.value?.id || 1
  const type = sceneTypeFix[id] || sceneTypeForChapter[id] || 'trend'
  return { ...(sceneDetails[type] || sceneDetails.range), ...(sceneOverride[id] || {}), type, scene: sceneFor(type) }
})
const labExplanation = computed(() => ({
  estructura: { title: 'Primero, el mapa', body: 'La estructura se lee siguiendo los máximos y mínimos relevantes, no cada vela aislada.', checks: ['Alcista: HH y HL progresivos.', 'Bajista: LH y LL progresivos.', 'Rango: el precio oscila sin progresión clara.'] },
  choch: { title: 'Ruptura contra la estructura previa', body: 'El CHOCH señala una posible transición. La dirección del CHOCH depende de la tendencia que se está quebrando.', checks: ['En tendencia bajista, observá el LH relevante.', 'En tendencia alcista, observá el HL relevante.', 'La ruptura es una alerta, no una garantía de reversión.'] },
  fvg: { title: 'Ineficiencia de tres velas', body: 'Una FVG representa un tramo donde el movimiento dejó un desequilibrio entre la primera y la tercera vela.', checks: ['Identificá correctamente los extremos de las tres velas.', 'No confundas cualquier hueco visual con una FVG.', 'La IFVG requiere que la zona sea atravesada y cambie de función.'] },
  ob: { title: 'Zona de origen de un impulso', body: 'Un Order Block es una zona asociada al origen de un movimiento relevante. No toda vela opuesta antes de un impulso es un OB de calidad.', checks: ['Buscá desplazamiento posterior.', 'Relacioná el bloque con estructura y liquidez.', 'Definí cuándo deja de ser válido.'] },
  breaker: { title: 'Un bloque fallido que cambia de función', body: 'El Breaker Block es un OB fallido que, tras una ruptura, puede actuar desde el lado opuesto como soporte o resistencia.', checks: ['Ubicá el OB original.', 'Confirmá la ruptura que lo invalida.', 'Observá el retesteo y la reacción en la zona.'] },
  liquidez: { title: 'Dónde pueden acumularse órdenes', body: 'Los máximos y mínimos evidentes pueden concentrar stops y órdenes pendientes. Un barrido no es lo mismo que una ruptura sostenida.', checks: ['BSL: liquidez sobre máximos.', 'SSL: liquidez bajo mínimos.', 'Esperá reacción o desplazamiento antes de inferir reversión.'] },
}[visualMode.value] || {}))

const allChecklistItems = computed(() => Object.values(checklist).flat())
function selectLesson(id) { selectedChapter.value = id; activeTab.value = 'curso'; quizAnswer.value = null; quizSubmitted.value = false }
function chooseAnswer(i) { quizAnswer.value = i; quizSubmitted.value = true }
function resetQuiz() { quizAnswer.value = null; quizSubmitted.value = false }
function toggleCompleted(id) {
  completed.value = completed.value.includes(id) ? completed.value.filter(n => n !== id) : [...completed.value, id]
  try { localStorage.setItem('smc-academy-completed-v1', JSON.stringify(completed.value)) } catch {}
}
function nextLesson() { if (selectedChapter.value < Math.max(...lessonCatalog.map(c => c.id))) selectLesson(selectedChapter.value + 1); else scrollTop() }
function previousLesson() { if (selectedChapter.value > 1) selectLesson(selectedChapter.value - 1) }
function scrollTop() { if (typeof window !== 'undefined') window.scrollTo({ top: 0, behavior: 'smooth' }) }
try {
  const saved = JSON.parse(localStorage.getItem('smc-academy-completed-v1') || '[]')
  if (Array.isArray(saved)) completed.value = saved.filter(id => lessonCatalog.some(c => c.id === id))
} catch { completed.value = [] }
watch(selectedChapter, () => { resetQuiz() })
</script>

<style scoped>
